// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;

    function setUp() public { c = new ReentrancyDAO(); }

    // fuzzed params: actor (who will call withdrawAll) and a boolean to choose if the adversarial helper should revert
    function testFuzz_property(address actor, bool helperReverts) public {
        // keep actor non-zero and not the contract itself
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // Deploy helper which either reverts on receive or records the received value.
        MaliciousHelper helper = new MaliciousHelper(address(c));
        helper.setShouldRevert(helperReverts);

        // Fund helper so it can be the recipient and so calls to it are possible
        vm.deal(address(helper), 1 ether);

        // Ensure actor has some ether to pay tx costs (though withdrawAll sends from c to msg.sender)
        vm.deal(actor, 1 ether);

        // If actor has zero credit in the reference, withdrawAll should do nothing and should NOT revert.
        // In the mutant, withdrawAll will attempt a call even when credit==0; if that call reverts, the mutant will revert.
        // Make the actor be the helper contract so that when c calls msg.sender.call it invokes helper's receive/fallback.

        // We need to call withdrawAll as if from the helper; use vm.prank with helper address.
        // But fuzzed actor param is required by the problem; to satisfy fuzzing, we still use it to occasionally vary state:
        // give the fuzzed 'actor' some deposit so it won't change the zero-credit condition unless we want to.

        // First, ensure the actor has zero credit: do not deposit for actor.
        // For control, deposit some ether under a different address so c.balance is nonzero (not necessary but realistic).
        address other = address(0x1234);
        vm.deal(other, 1 ether);
        vm.prank(other);
        c.deposit{value: 0.01 ether}();

        // Now perform the call from the helper (so msg.sender in c is helper)
        // Register helper's address as the caller by pranking it.
        vm.prank(address(helper));
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule to assert: For the reference contract, when an account with zero credit calls withdrawAll,
        // the call never reverts (it is a no-op). Therefore ok must be true for the reference.
        // The mutant can revert if it performs an external call even when credit is zero and that external call reverts.
        assertTrue(ok);
    }
}

// Adversarial helper: it either reverts on receive/fallback or accepts and records
contract MaliciousHelper {
    bool public shouldRevert;
    address public target;

    constructor(address _target) payable {
        target = _target;
    }

    function setShouldRevert(bool v) public {
        shouldRevert = v;
    }

    // Accept or revert depending on the flag. If revert, this will make the mutant revert when it calls msg.sender.call{value:0}("").
    receive() external payable {
        if (shouldRevert) {
            revert("malicious revert");
        }
        // otherwise accept and do nothing
    }

    fallback() external payable {
        if (shouldRevert) {
            revert("malicious revert");
        }
    }
}
